// interleave extras to make exactly 100 (a few near-duplicates are retired)
const RETIRED = ['Pyramid of the Sphinx', 'Valhalla Gold Hall', 'Atlantean Kraken Gate', 'Inside a Giant Clock', "Gingerbread Witch's House", 'Mermaid Lagoon Grotto', 'Asteroid Mining Rig', 'Lunar Casino Resort', 'Ice Hotel Grand Ball'];
const base = THEMES.filter((t) => !RETIRED.includes(t.n));
const extras = EXTRA.filter((t) => !RETIRED.includes(t.n));
const insertAt = [6, 14, 23, 31, 39, 47, 55, 63, 71, 79];
const merged = base.slice();
insertAt.slice(0, extras.length).reverse().forEach((pos, i) => {
  merged.splice(pos, 0, extras[extras.length - 1 - i]);
});
export const LEVELS = merged.slice(0, 100);
